from pathlib import Path
import json
root=Path('frontend/public/concepts')
out=root/'logo-ideas'
concepts=[
('Pomegranate wishes','A cut pomegranate turns an Azerbaijani symbol of abundance into wishes shared with someone you love.',
'<path fill-rule="evenodd" d="M23 18 19 7 28 12 33 3 38 13 48 9 44 20C54 25 59 33 58 42 57 55 46 62 32 62S7 54 6 42C5 31 12 23 23 18ZM32 25C21 25 14 32 14 42S22 54 32 54 50 50 50 40 43 25 32 25Z"/><path d="M32 28C25 34 25 39 32 39S39 34 32 28ZM21 39C16 46 20 51 26 48S28 41 21 39ZM43 39C36 41 35 46 40 49S49 46 43 39Z"/>'),
('A day circled','An open, hand-drawn circle singles out one day: someone important is already on your mind.',
'<path d="M48 12C37 5 22 7 13 17 2 30 7 47 20 54 33 62 49 54 55 42 59 33 57 25 52 21" fill="none" stroke="currentColor" stroke-width="8" stroke-linecap="round"/><circle cx="31" cy="33" r="7"/>'),
('Kept in mind','A deeply folded page corner is the small physical gesture of marking something worth returning to.',
'<path d="M10 5H36L55 24V59H10V5ZM18 13V51H47V29H36C30 29 28 25 28 19V13H18Z" fill-rule="evenodd"/><path d="M36 5V20C36 23 38 24 41 24H55Z"/>'),
('Held close','Two open arms hold a person at their center, putting the recipient ahead of the gift.',
'<circle cx="32" cy="22" r="8"/><path d="M22 7C10 12 4 23 6 36 8 48 18 54 30 54V45C20 44 13 39 14 31 15 23 19 17 25 13 29 10 26 5 22 7ZM42 57C54 52 60 41 58 28 57 23 51 23 49 28 45 39 39 45 33 48 28 51 29 59 35 59Z"/>'),
('A wish on its way','An angular paper bird carries the feeling of a personal note from one person to another.',
'<path d="M5 7 36 23 46 15 59 19 49 28 42 43 12 57 19 36 5 7ZM20 23 27 36 35 32 20 23Z" fill-rule="evenodd"/>'),
('Make a wish','One birthday candle captures the familiar pause before a person makes a wish.',
'<path d="M33 3C31 10 23 13 23 21 23 33 42 32 42 21 42 14 36 8 33 3ZM18 37C18 34 23 33 27 36 31 39 35 38 39 36 43 33 47 34 47 38V58C47 61 18 61 18 58V37Z"/>'),
('A personal signature','A free-standing, handwritten double valley gives Wisher the informality of signing a card by hand.',
'<path d="M5 25C13 17 20 14 22 19 24 23 19 38 21 40 23 42 31 23 37 24 43 25 37 42 42 42 45 42 49 23 56 10 61 1 66 7 61 18 55 33 49 54 39 54 31 54 31 46 31 40 25 49 20 57 13 54 7 51 12 33 13 29 14 24 7 31 5 30 3 29 3 27 5 25Z"/>'),
('Words for you','Two generous opening quotation marks make the personal words inside a greeting the identity.',
'<path d="M28 8C15 10 5 21 5 34 5 45 12 50 19 48 28 46 29 34 22 30L17 28C18 21 22 16 28 12V8ZM58 14C45 16 35 27 35 40 35 51 42 56 49 54 58 52 59 40 52 36L47 34C48 27 52 22 58 18V14Z"/>'),
('A wish unfolding','One seed held in an opening leaf suggests a small thoughtful gesture growing into joy.',
'<path d="M29 5C24 10 20 15 20 21 20 31 36 31 36 21 36 16 32 9 29 5ZM7 31C6 45 15 59 31 60 29 47 20 37 7 31ZM57 16C47 27 34 28 31 41 29 48 32 55 36 60 54 55 61 35 57 16Z"/>')
]
for i,(name,why,shape) in enumerate(concepts,1):
 for suffix,color in [('', '#a3122f'),('-white','#ffffff')]:
  svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64" fill="{color}" color="{color}" role="img"><title>{name}</title>{shape}</svg>\n'
  (out/f'{i:02d}{suffix}.svg').write_text(svg)

def samples(i,white=False):
 suffix='-white' if white else ''
 return '<div class="swatch '+('red' if white else 'white')+'"><div class="large"><img alt="" src="logo-ideas/%02d%s.svg" width="180" height="180"><span>180 px</span></div><div class="sizes">'%(i,suffix)+''.join(f'<div><img alt="" src="logo-ideas/{i:02d}{suffix}.svg" width="{z}" height="{z}"><span>{z} px</span></div>' for z in [16,32,64])+'</div></div>'
cards=[]
for i,(name,why,shape) in enumerate(concepts,1):
 cards.append(f'''<article id="idea-{i}" aria-labelledby="title-{i}"><div class="heading"><span class="number">{i:02d}</span><div><h2 id="title-{i}">{name}</h2><p>{why}</p></div></div><div class="samples">{samples(i)}{samples(i,True)}</div><div class="lockup" aria-label="Concept {i} with Wisher wordmark on the red header"><img src="logo-ideas/{i:02d}-white.svg" width="32" height="32" alt="{name} icon"><span class="wordmark">wisher<span>.az</span></span><span class="header-label">Header preview</span></div><div class="files"><a href="logo-ideas/{i:02d}.svg" download>Red SVG</a><a href="logo-ideas/{i:02d}-white.svg" download>White SVG</a><a href="#top">Back to overview</a></div></article>''')
html='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Wisher - Nine logo ideas</title>
<style>
@font-face{font-family:Fraunces;src:url('logo-ideas/fraunces.woff2') format('woff2');font-weight:100 900;font-display:swap}
@font-face{font-family:Manrope;src:url('logo-ideas/manrope.woff2') format('woff2');font-weight:200 800;font-display:swap}
*{box-sizing:border-box}html{scroll-padding-top:20px}body{margin:0;background:white;color:#23171b;font:16px/1.55 Manrope,Arial,sans-serif}a{color:inherit;text-underline-offset:4px}a:focus-visible{outline:3px solid #0f6b4f;outline-offset:4px}header{padding:40px 48px 28px;max-width:1440px;margin:auto}h1{font:700 48px/1.1 Fraunces,Georgia,serif;letter-spacing:-.03em;margin:0 0 16px}header p{max-width:760px;margin:0 0 20px}nav{display:flex;flex-wrap:wrap;gap:8px}nav a{min-width:48px;min-height:44px;display:grid;place-items:center;border:1px solid #d9cbd0;text-decoration:none;font-weight:700}nav a:hover{background:#a3122f;color:white}.overview{display:grid;grid-template-columns:repeat(9,1fr);margin:26px 0 0;border-top:1px solid #d9cbd0;border-bottom:1px solid #d9cbd0;padding:22px 0;gap:12px}.overview a{display:flex;flex-direction:column;align-items:center;gap:12px;text-decoration:none;font-size:14px;min-width:44px;min-height:44px}.overview img{width:56px;height:56px}.review{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:36px;padding:10px 48px 48px;max-width:1440px;margin:auto}article{border-top:2px solid #23171b;padding-top:22px;min-width:0}.heading{display:flex;gap:20px;min-height:142px;padding-bottom:20px}.number{font:500 34px/1.2 Fraunces,serif;font-variant-numeric:tabular-nums;min-width:44px}h2{font:700 27px/1.2 Fraunces,serif;margin:0 0 10px}.heading p{font-size:15px;margin:0;max-width:470px}.samples{display:grid;grid-template-columns:1fr 1fr}.swatch{padding:24px 14px 18px;min-width:0}.white{background:#fff;color:#a3122f;border:1px solid #eadfe1}.red{background:#a3122f;color:#fff}.large{display:flex;flex-direction:column;align-items:center;gap:12px}.large img{display:block;flex-shrink:0}.swatch span{font-size:13px;font-variant-numeric:tabular-nums}.sizes{display:flex;align-items:end;justify-content:space-around;gap:16px;margin-top:26px;min-height:95px}.sizes>div{display:flex;flex-direction:column;align-items:center;justify-content:end;gap:10px}.sizes img{display:block;flex-shrink:0}.lockup{display:flex;align-items:center;gap:10px;background:#a3122f;color:white;padding:20px 24px;margin-top:12px;min-height:80px}.lockup img{flex-shrink:0}.wordmark{font:700 32px/1 Fraunces,Georgia,serif;letter-spacing:-.02em;white-space:nowrap}.wordmark>span{font:600 14px Manrope,Arial,sans-serif;margin-left:3px;letter-spacing:0}.header-label{font-size:13px;margin-left:auto}.files{display:flex;flex-wrap:wrap;gap:12px 24px;padding-top:8px}.files a{display:flex;align-items:center;min-height:44px;font-size:14px}.files a:last-child{margin-left:auto}footer{max-width:1440px;margin:auto;padding:0 48px 48px;font-size:14px;color:#59454d}footer p{max-width:850px}.note{font-weight:700;color:#0f6b4f}
@media(max-width:1000px){.review{gap:24px;padding:10px 24px 36px}header{padding:32px 24px 24px}.heading{min-height:180px}.header-label{display:none}.swatch{padding:20px 8px}.large img{width:180px;height:180px}.samples{grid-template-columns:1fr}.swatch{display:grid;grid-template-columns:180px 1fr;gap:18px;align-items:center}.sizes{flex-direction:column;margin:0;gap:14px;align-items:center}.overview img{width:44px;height:44px}.overview{gap:8px}footer{padding:0 24px 36px}}
@media(max-width:700px){header{padding:28px 16px 20px}h1{font-size:36px;max-width:320px}header p{font-size:15px}.overview{grid-template-columns:repeat(3,1fr);gap:24px 12px}.overview img{width:56px;height:56px}nav{gap:6px}nav a{min-width:44px;flex:0 0 48px;min-height:44px}.review{display:block;padding:0 16px 24px}article{padding-top:22px;margin-bottom:36px}.heading{min-height:0;gap:12px;padding-bottom:24px}.heading p{font-size:15px}h2{font-size:27px}.number{min-width:38px;font-size:30px}.swatch{grid-template-columns:180px 1fr;padding:22px 12px;gap:12px}.samples{grid-template-columns:1fr}.lockup{padding:20px 16px}.files{gap:8px 16px}.files a{font-size:13px}.files a:last-child{margin-left:0}footer{padding:0 16px 32px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
</style></head><body><header id="top"><h1>Nine ideas for<br>Wisher's next icon.</h1><p>Pick the idea by number. Each is shown at actual 16, 32, 64 and 180 px sizes, on white and red, then beside the approved wordmark. These are proposals, not changes to the site.</p><nav aria-label="Jump to a concept">'''+''.join(f'<a href="#idea-{i}" aria-label="Concept {i}: {name}">{i:02d}</a>' for i,(name,_,__) in enumerate(concepts,1))+'''</nav><div class="overview" aria-label="All nine silhouettes">'''+''.join(f'<a href="#idea-{i}" aria-label="Concept {i}: {name}"><img src="logo-ideas/{i:02d}.svg" alt="" width="56" height="56"><span>{i:02d}</span></a>' for i,(name,_,__) in enumerate(concepts,1))+'''</div></header><main class="review">'''+''.join(cards)+'''</main><footer><p class="note">No concept has been selected or installed.</p><p>One image-generated exploration board informed these manually drawn vectors. All icons use a single solid color and transparent negative space. Red #a3122f and the Fraunces wordmark follow the approved Wisher direction. These are original proposals; trademark clearance has not been performed.</p></footer></body></html>'''
(root/'logo-ideas.html').write_text(html)
Path('docs/evidence/logo-ideas/concepts.json').write_text(json.dumps([{'number':i,'name':name,'rationale':why} for i,(name,why,_) in enumerate(concepts,1)],indent=2)+'\n')
